import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
// Specialized ConvTranspose3d forward kernel (stride=1, padding=0,
// output_padding=0, groups=1, dilation=1, fp32).
// Input : (16, 32, 16, 32, 64) contiguous fp32
// Weight: (32, 16, 3, 5, 7)  contiguous fp32 (ic, oc, kd, kh, kw)
// Bias  : (16) contiguous fp32 (optional)
// Output: (16, 16, 18, 36, 70) contiguous fp32
// Structural optimization: shared-memory staging of the reusable input
// tile. Each CTA covers 16 output W positions for one (n, oc, d, h); the
// 16x16 threads cooperatively stage a zero-padded 16ch x 3di x 5hi x 22wi
// input window into shared memory (two channel halves), so each global
// input element is fetched once per CTA instead of once per W tap, and
// the 3x5x7 tap loop reads from shared memory. Partial sums across the
// 16 ty channel lanes are reduced through shared memory as before.
.visible .entry conv_transpose3d_kernel(
    .param .u64 param_in,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_out,
    .param .u32 param_total,
    .param .u32 param_has_bias
)
{
    .reg .pred %p, %pt, %rvalid, %pd, %ph, %pw0, %pw1, %pt6;
    .reg .b32 %r_cta, %tx, %ty;
    .reg .b32 %wb, %t, %n, %oc, %d, %h, %w, %w0;
    .reg .b32 %ic, %half, %kd, %kh, %kw;
    .reg .b32 %dia, %hia, %wia, %dm2, %hm4, %w0m6;
    .reg .b32 %tmp, %tmp2, %tmp3, %tmp4, %idx, %in_off, %w_off;
    .reg .b32 %sh_base_f, %sh_base_f6, %sidx, %out_idx, %red_i;
    .reg .b32 %total, %hasbias;
    .reg .b64 %in_base, %w_base, %b_base, %out_base;
    .reg .b64 %addr, %g_addr, %sh_addr, %sh_in_g, %sh_part_g;
    .reg .f32 %sum, %acc, %iv, %wv, %bv, %pv;
    .shared .align 4 .b8 sh_in[21120];
    .shared .align 4 .b8 sh_part[1024];
    ld.param.u64 %in_base, [param_in];
    ld.param.u64 %w_base, [param_w];
    ld.param.u64 %b_base, [param_b];
    ld.param.u64 %out_base, [param_out];
    ld.param.u32 %total, [param_total];
    ld.param.u32 %hasbias, [param_has_bias];
    mov.u32 %r_cta, %ctaid.x;
    mov.u32 %tx, %tid.x;         // 0..15 output W lane inside tile
    mov.u32 %ty, %tid.y;         // 0..15 cooperative input-channel half
    // CTA tile decomposition: 5 W-tiles per (n, oc, d, h).
    rem.u32 %wb, %r_cta, 5;
    div.u32 %t, %r_cta, 5;
    rem.u32 %h, %t, 36;
    div.u32 %t, %t, 36;
    rem.u32 %d, %t, 18;
    div.u32 %t, %t, 18;
    rem.u32 %oc, %t, 16;
    div.u32 %n, %t, 16;
    shl.b32 %w0, %wb, 4;
    add.s32 %w, %w0, %tx;          // output W coordinate for this lane
    setp.lt.u32 %rvalid, %w, 70;
    // Staging constants (signed; negative handled by bounds predicates).
    sub.s32 %dm2, %d, 2;
    sub.s32 %hm4, %h, 4;
    sub.s32 %w0m6, %w0, 6;
    // Per-thread shared float base: ty*330 + tx (row stride 22 floats).
    mul.lo.s32 %sh_base_f, %ty, 330;
    add.s32 %sh_base_f, %sh_base_f, %tx;
    add.s32 %sh_base_f6, %sh_base_f, 6;
    mov.u64 %sh_in_g, sh_in;
    mov.u64 %sh_part_g, sh_part;
    mov.f32 %sum, 0f00000000;
    mov.u32 %half, 0;
HALF_LOOP:
    setp.lt.u32 %p, %half, 2;
    @!%p bra HALF_DONE;
    shl.b32 %tmp, %half, 4;
    add.s32 %ic, %tmp, %ty;        // ic = ty + 16*half
    shl.b32 %tmp, %n, 5;
    add.s32 %tmp, %tmp, %ic;
    shl.b32 %in_off, %tmp, 15;     // channel base (floats)
    // ---- Stage this 16-channel half: zero-padded 3x5x22 window ----
    mov.u32 %kd, 0;
ST_DI:
    setp.lt.u32 %p, %kd, 3;
    @!%p bra ST_DI_END;
    add.s32 %dia, %dm2, %kd;       // staged di -> actual input depth
    setp.ge.s32 %pd, %dia, 0;
    setp.lt.s32 %pt, %dia, 16;
    and.pred %pd, %pd, %pt;
    shl.b32 %tmp, %dia, 11;        // dia * 2048
    add.s32 %tmp, %tmp, %in_off;   // global di slab base (floats)
    mul.lo.s32 %tmp2, %kd, 110;
    add.s32 %tmp2, %tmp2, %sh_base_f;
    mov.u32 %kh, 0;
ST_HI:
    setp.lt.u32 %p, %kh, 5;
    @!%p bra ST_HI_END;
    add.s32 %hia, %hm4, %kh;       // staged hi -> actual input height
    setp.ge.s32 %ph, %hia, 0;
    setp.lt.s32 %pt, %hia, 32;
    and.pred %ph, %ph, %pt;
    and.pred %ph, %ph, %pd;
    shl.b32 %tmp3, %hia, 6;        // hia * 64
    add.s32 %tmp3, %tmp3, %tmp;    // global row base (floats)
    mul.lo.s32 %tmp4, %kh, 22;
    add.s32 %tmp4, %tmp4, %tmp2;
    shl.b32 %tmp4, %tmp4, 2;
    cvt.u64.u32 %addr, %tmp4;
    add.s64 %sh_addr, %sh_in_g, %addr;
    // Element 0 of the row: wi_local = tx
    add.s32 %wia, %w0m6, %tx;
    setp.ge.s32 %pw0, %wia, 0;
    setp.lt.s32 %pt, %wia, 64;
    and.pred %pw0, %pw0, %pt;
    and.pred %pw0, %pw0, %ph;
    add.s32 %idx, %tmp3, %wia;
    mul.wide.u32 %g_addr, %idx, 4;
    add.s64 %g_addr, %g_addr, %in_base;
    mov.f32 %iv, 0f00000000;
    @%pw0 ld.global.f32 %iv, [%g_addr];
    st.shared.f32 [%sh_addr], %iv;
    // Element 1 of the row: wi_local = tx + 16 (only tx < 6)
    setp.lt.u32 %pt6, %tx, 6;
    @!%pt6 bra ST_HI_NEXT;
    add.s32 %wia, %wia, 16;
    setp.lt.s32 %pw1, %wia, 64;
    and.pred %pw1, %pw1, %ph;
    add.s32 %idx, %tmp3, %wia;
    mul.wide.u32 %g_addr, %idx, 4;
    add.s64 %g_addr, %g_addr, %in_base;
    mov.f32 %iv, 0f00000000;
    @%pw1 ld.global.f32 %iv, [%g_addr];
    add.s64 %sh_addr, %sh_addr, 64;
    st.shared.f32 [%sh_addr], %iv;
ST_HI_NEXT:
    add.s32 %kh, %kh, 1;
    bra ST_HI;
ST_HI_END:
    add.s32 %kd, %kd, 1;
    bra ST_DI;
ST_DI_END:
    bar.sync 0;
    // ---- Compute this half from the staged shared tile ----
    // Weight channel base: (ic*16 + oc) * (3*5*7).
    shl.b32 %tmp, %ic, 4;
    add.s32 %tmp, %tmp, %oc;
    mul.lo.s32 %w_off, %tmp, 105;
    mov.u32 %kd, 0;
C_KD:
    setp.lt.u32 %p, %kd, 3;
    @!%p bra C_KD_END;
    mov.u32 %tmp, 2;
    sub.s32 %tmp, %tmp, %kd;       // staged di index = 2 - kd
    mul.lo.s32 %tmp, %tmp, 110;
    add.s32 %tmp, %tmp, %sh_base_f6;
    mul.lo.s32 %tmp2, %kd, 35;     // kd * (5*7)
    add.s32 %tmp2, %tmp2, %w_off;
    mov.u32 %kh, 0;
C_KH:
    setp.lt.u32 %p, %kh, 5;
    @!%p bra C_KH_END;
    mov.u32 %tmp3, 4;
    sub.s32 %tmp3, %tmp3, %kh;     // staged hi index = 4 - kh
    mul.lo.s32 %tmp3, %tmp3, 22;
    add.s32 %tmp3, %tmp3, %tmp;
    shl.b32 %tmp3, %tmp3, 2;       // byte offset for (kd,kh,kw=0)
    cvt.u64.u32 %addr, %tmp3;
    add.s64 %sh_addr, %sh_in_g, %addr;
    mul.lo.s32 %tmp4, %kh, 7;      // kh * 7
    add.s32 %tmp4, %tmp4, %tmp2;
    mul.wide.u32 %g_addr, %tmp4, 4;
    add.s64 %g_addr, %g_addr, %w_base;
    mov.u32 %kw, 0;
C_KW:
    setp.lt.u32 %p, %kw, 7;
    @!%p bra C_KW_END;
    ld.shared.f32 %iv, [%sh_addr]; // staged wi index = tx + 6 - kw
    ld.global.f32 %wv, [%g_addr];  // broadcast within warp
    fma.rn.f32 %sum, %iv, %wv, %sum;
    sub.s64 %sh_addr, %sh_addr, 4;
    add.s64 %g_addr, %g_addr, 4;
    add.s32 %kw, %kw, 1;
    bra C_KW;
C_KW_END:
    add.s32 %kh, %kh, 1;
    bra C_KH;
C_KH_END:
    add.s32 %kd, %kd, 1;
    bra C_KD;
C_KD_END:
    bar.sync 0;                    // protect sh_in overwrite next half
    add.s32 %half, %half, 1;
    bra HALF_LOOP;
HALF_DONE:
    // Cooperative reduction across the 16 ty lanes for each tx output.
    shl.b32 %sidx, %ty, 4;
    add.s32 %sidx, %sidx, %tx;
    shl.b32 %sidx, %sidx, 2;
    cvt.u64.u32 %addr, %sidx;
    add.s64 %addr, %addr, %sh_part_g;
    st.shared.f32 [%addr], %sum;
    bar.sync 0;
    setp.ne.u32 %p, %ty, 0;
    @%p bra DONE;
    @!%rvalid bra DONE;
    mov.f32 %acc, 0f00000000;
    mov.u32 %red_i, 0;
RED_LOOP:
    setp.lt.u32 %p, %red_i, 16;
    @!%p bra RED_END;
    shl.b32 %sidx, %red_i, 4;
    add.s32 %sidx, %sidx, %tx;
    shl.b32 %sidx, %sidx, 2;
    cvt.u64.u32 %addr, %sidx;
    add.s64 %addr, %addr, %sh_part_g;
    ld.shared.f32 %pv, [%addr];
    add.f32 %acc, %acc, %pv;
    add.s32 %red_i, %red_i, 1;
    bra RED_LOOP;
RED_END:
    setp.eq.u32 %p, %hasbias, 0;
    @%p bra STORE;
    mul.wide.u32 %addr, %oc, 4;
    add.s64 %addr, %addr, %b_base;
    ld.global.f32 %bv, [%addr];
    add.f32 %acc, %acc, %bv;
STORE:
    // Contiguous output index (n, oc, d, h, w).
    shl.b32 %tmp, %n, 4;
    add.s32 %tmp, %tmp, %oc;
    mul.lo.s32 %tmp, %tmp, 18;
    add.s32 %tmp, %tmp, %d;
    mul.lo.s32 %tmp, %tmp, 36;
    add.s32 %tmp, %tmp, %h;
    mul.lo.s32 %out_idx, %tmp, 70;
    add.s32 %out_idx, %out_idx, %w;
    mul.wide.u32 %addr, %out_idx, 4;
    add.s64 %addr, %addr, %out_base;
    st.global.f32 [%addr], %acc;
DONE:
    ret;
}
"""

_ptx_module = None


def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module


def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_kernel")


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution operation with asymmetric input and
    kernel sizes, computed entirely by a custom PTX kernel.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (tuple): Tuple of 3 integers representing the kernel size in the form (depth, height, width).
        stride (tuple, optional): Tuple of 3 integers representing the stride in the form (depth, height, width). Defaults to (1, 1, 1).
        padding (tuple, optional): Tuple of 3 integers representing the padding in the form (depth, height, width). Defaults to (0, 0, 0).
        output_padding (tuple, optional): Tuple of 3 integers representing the output padding in the form (depth, height, width). Defaults to (0, 0, 0).
        groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed 3D convolution.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, depth_in, height_in, width_in).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, depth_out, height_out, width_out).
        """
        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        stride = self.conv_transpose3d.stride
        padding = self.conv_transpose3d.padding
        output_padding = self.conv_transpose3d.output_padding
        dilation = self.conv_transpose3d.dilation

        batch, in_ch, d_in, h_in, w_in = x.shape
        kd, kh, kw = weight.shape[2], weight.shape[3], weight.shape[4]
        out_ch = weight.shape[1] * self.conv_transpose3d.groups
        d_out = (d_in - 1) * stride[0] - 2 * padding[0] + dilation[0] * (kd - 1) + output_padding[0] + 1
        h_out = (h_in - 1) * stride[1] - 2 * padding[1] + dilation[1] * (kh - 1) + output_padding[1] + 1
        w_out = (w_in - 1) * stride[2] - 2 * padding[2] + dilation[2] * (kw - 1) + output_padding[2] + 1

        out = torch.empty((batch, out_ch, d_out, h_out, w_out), device=x.device, dtype=x.dtype)
        total = out.numel()

        if bias is not None:
            bias_arg = bias
            has_bias = 1
        else:
            bias_arg = weight  # Dummy pointer; never dereferenced.
            has_bias = 0

        module = _get_ptx_module()
        module.launch(
            "conv_transpose3d_kernel",
            grid=(batch * out_ch * d_out * h_out * ((w_out + 15) // 16), 1, 1),
            block=(16, 16, 1),
            arguments=[x, weight, bias_arg, out, u32(total), u32(has_bias)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

