    // Valid kernel tap ranges (input index = output index - tap index).
    sub.s32 %tmp, %d, 15;
    max.s32 %kd_lo, %tmp, 0;
    min.s32 %kd_hi, %d, 2;
    sub.s32 %tmp, %h, 31;
    max.s32 %kh_lo, %tmp, 0;
    min.s32 %kh_hi, %h, 4;
    sub.s32 %tmp, %w, 63;
    max.s32 %kw_lo, %tmp, 0;
    min.s32 %kw_hi, %w, 6;

    mov.f32 %sum, 0f00000000;
    mov.u32 %ic, 0;

IC_LOOP:
    setp.lt.u32 %p, %ic, 32;
    @!%p bra IC_END;

    // Input channel base: (n*32 + ic) * (16*32*64)
    shl.b32 %tmp, %n, 5;
    add.s32 %tmp, %tmp, %ic;
    shl.b32 %in_off, %tmp, 15;

    // Weight channel base: (ic*16 + oc) * (3*5*7)
    shl.b32 %tmp, %ic, 4;
    add.s32 %tmp, %tmp, %oc;
    mul.lo.s32 %w_off, %tmp, 105;

    mov.u32 %kd, %kd_lo;
KD_LOOP:
    setp.le.u32 %p, %kd, %kd_hi;
    @!%p bra KD_END;
    sub.s32 %di, %d, %kd;
    shl.b32 %tmp, %di, 11;          // di * 2048
    add.s32 %in_d, %in_off, %tmp;
    mul.lo.s32 %tmp, %kd, 35;       // kd * (5*7)
    add.s32 %w_d, %w_off, %tmp;

    mov.u32 %kh, %kh_lo;
KH_LOOP:
    setp.le.u32 %p, %kh, %kh_hi;
    @!%p bra KH_END;
    sub.s32 %hi, %h, %kh;
    shl.b32 %tmp, %hi, 6;           // hi * 64
    add.s32 %in_h, %in_d, %tmp;
    mul.lo.s32 %tmp, %kh, 7;        // kh * 7
    add.s32 %w_h, %w_d, %tmp;

    mov.u32 %kw, %kw_lo;
KW_LOOP:
    setp.le.u32 %p, %kw, %kw_hi;
    @!%p bra KW_END;
    sub.s32 %wi, %w, %kw;
    add.s32 %idx, %in_h, %wi;
    mul.wide.u32 %addr, %idx, 4;
    add.s64 %addr, %addr, %in_base;
    ld.global.f32 %iv, [%addr];
    add.s32 %idx, %w_h, %kw;
    mul.wide.u32 %addr, %idx, 4;
    add.s64 %addr, %addr, %w_base;
    ld.global.f32 %wv, [%addr];
    fma.rn.f32 %sum, %iv, %wv, %sum;
    add.s32 %kw, %kw, 1;
    bra KW_LOOP;
KW_END:
    add.s32 %kh, %kh, 1;
    bra KH_LOOP;
KH_END:
    add.s32 %kd, %kd, 1;
    bra KD_LOOP;
KD_END:
    add.s32 %ic, %ic, 1;
    bra IC_LOOP;
IC_END:

    setp.eq.u32 %p, %hasbias, 0;
    @%p bra STORE;
    mul.wide.u32 %addr, %oc, 4;
    add.s64 %addr, %addr, %b_base;
    ld.global.f32 %bv, [%addr];
    add.f32 %sum, %sum, %bv;

STORE:
    mul.wide.u32 %addr, %gid, 4;
    add.s64 %addr, %addr, %out_base;
    st.global.f32 [%addr], %sum;

DONE:
    ret;
