_ptx_module = None


def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module


def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_kernel")


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution operation with asymmetric input and
    kernel sizes, computed entirely by a custom PTX kernel.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (tuple): Tuple of 3 integers representing the kernel size in the form (depth, height, width).
        stride (tuple, optional): Tuple of 3 integers representing the stride in the form (depth, height, width). Defaults to (1, 1, 1).
        padding (tuple, optional): Tuple of 3 integers representing the padding in the form (depth, height, width). Defaults to (0, 0, 0).
        output_padding (tuple, optional): Tuple of 3 integers representing the output padding in the form (depth, height, width). Defaults to (0, 0, 0).
        groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed 3D convolution.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, depth_in, height_in, width_in).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, depth_out, height_out, width_out).
        """
        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        stride = self.conv_transpose3d.stride
        padding = self.conv_transpose3d.padding
        output_padding = self.conv_transpose3d.output_padding
        dilation = self.conv_transpose3d.dilation

        batch, in_ch, d_in, h_in, w_in = x.shape
        kd, kh, kw = weight.shape[2], weight.shape[3], weight.shape[4]
        out_ch = weight.shape[1] * self.conv_transpose3d.groups
        d_out = (d_in - 1) * stride[0] - 2 * padding[0] + dilation[0] * (kd - 1) + output_padding[0] + 1
        h_out = (h_in - 1) * stride[1] - 2 * padding[1] + dilation[1] * (kh - 1) + output_padding[1] + 1
        w_out = (w_in - 1) * stride[2] - 2 * padding[2] + dilation[2] * (kw - 1) + output_padding[2] + 1

        out = torch.empty((batch, out_ch, d_out, h_out, w_out), device=x.device, dtype=x.dtype)
        total = out.numel()

        if bias is not None:
            bias_arg = bias
            has_bias = 1
        else:
            bias_arg = weight  # Dummy pointer; never dereferenced.
            has_bias = 0

        module = _get_ptx_module()
        module.launch(
            "conv_transpose3d_kernel",
            grid=((total + 255) // 256, 1, 1),
            block=(256, 1, 1),
            arguments=[x, weight, bias_arg, out, u32(total), u32(has_bias)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
